sys_script.script:
(function executeRule(current, previous) {

    var newStatus = current.getValue('booking_status');
    var oldStatus = previous.getValue('booking_status');

    // Run only when changing to Cancelled
    if (newStatus == 'cancelled' && oldStatus != 'cancelled') {

        // Cancellation reason is required
        if (gs.nil(current.getValue('cancellation_reason'))) {

            gs.addErrorMessage(
                'Cancellation Reason is required to cancel the booking.'
            );

            current.setAbortAction(true);
            return;
        }

        // Completed bookings cannot be cancelled
        if (oldStatus == 'completed') {

            gs.addErrorMessage(
                'A completed parking booking cannot be cancelled.'
            );

            current.setAbortAction(true);
            return;
        }

        // Expired bookings cannot be cancelled
        if (oldStatus == 'expired') {

            gs.addErrorMessage(
                'An expired parking booking cannot be cancelled.'
            );

            current.setAbortAction(true);
        }
    }

})(current, previous);
